      `  P/E: ${f.pe_ratio||'N/A'} | P/S: ${f.ps_ratio||'N/A'} | P/B: ${f.pb_ratio||'N/A'}`,
      `  Rev Growth YoY: ${revGrowth} | Gross Margin: ${grossMargin} | Net Margin: ${netMargin}`,
      `  Beta: ${f.beta||'N/A'} | Consensus: ${analystStr} | PT: ${ptStr}`,
      `  Earnings Risk: ${earningsTag}`,
    ].join('\n');
  }).join('\n\n');
}

