    orderSide = 'sell'; orderEffect = null;
  } else if (action.action === 'SHORT') {
    orderSide = 'sell'; orderEffect = null;  // Alpaca auto-detects short when no position exists
  } else if (action.action === 'COVER') {
    orderSide = 'buy'; orderEffect = null;
  }

  const marketOrderPayload = {
    symbol:         ticker,
    qty:            shares ? shares.toString() : null,
    notional:       shares ? null : action.size_usd.toString(),  // use notional if shares not computed
    side:           orderSide,
    type:           'market',
    time_in_force:  'day',
    extended_hours: false,
  };
  // Clean nulls
  if (marketOrderPayload.qty)      delete marketOrderPayload.notional;
  if (!marketOrderPayload.qty)     delete marketOrderPayload.qty;
  if (!marketOrderPayload.notional) delete marketOrderPayload.notional;

  // Trailing stop payload (only for BUY / SHORT)
  const trailStopPayload = (action.action === 'BUY' || action.action === 'SHORT') ? {
    symbol:         ticker,
    qty:            shares ? shares.toString() : action.size_usd.toString(),
    side:           action.action === 'BUY' ? 'sell' : 'buy',  // opposite side
    type:           'trailing_stop',
    trail_percent:  stopPct.toString(),
    time_in_force:  'gtc',
  } : null;

  return {
    ...action,
    shares:               shares,
    estimated_price:      price,
    stop_pct_used:        stopPct,
    needs_trailing_stop:  action.action === 'BUY' || action.action === 'SHORT',
    order_payload:        marketOrderPayload,
    trail_stop_payload:   trailStopPayload,
  };
});

// ── SEPARATE SELL/COVER FOR POST-MORTEM ──────────────────────────────────────
const closedPositions = enrichedActions.filter(a => a.action === 'SELL' || a.action === 'COVER');
const openingActions  = enrichedActions.filter(a => a.action === 'BUY'  || a.action === 'SHORT');

// For each closed position, build the post-mortem webhook payload
const exitDate = orchInput.portfolio_state.session_id.split('_')[0];
const postMortemPayloads = closedPositions.map(action => {
  const ticker   = action.ticker;
  const position = (state.positions || []).find(p => p.symbol === ticker);

  // Approximate entry date as 30 days before exit — we don't track open date in DB yet.
  // This ensures Load Signals During Hold gets a valid date (not null → SQL error).
  const entryDate = new Date(new Date(exitDate).getTime() - 30 * 86400000)
                      .toISOString().split('T')[0];

  return {
    ticker,
    niche:                       action.niche,
    side:                        action.action === 'SELL' ? 'LONG' : 'SHORT',
    direction:                   action.action === 'SELL' ? 'long' : 'short',
    action:                      action.action,
    exit_reason:                 action.exit_reason,
    exit_price:                  priceMap[ticker] ? priceMap[ticker].current : null,
    entry_price:                 position ? parseFloat(position.avg_entry_price) : null,
    entry_date:                  entryDate,
    exit_date:                   exitDate,
    session_id:                  orchInput.portfolio_state.session_id,
    signal_history_pattern:      action.signal_history_pattern      || null,
    thesis:                      action.thesis                      || null,
    size_usd:                    action.size_usd                    || null,
    entry_specialist_confidence: action.confidence                  || null,
    entry_effective_confidence:  action.effective_confidence        || null,
    specialists_at_exit:         orchInput.specialists_summary,
  };
});

// ── DERIVE MARKET OPEN FROM SESSION TYPE (not LLM judgment) ──────────────────
// The LLM doesn't reliably know what morning/midday/close map to in ET.
// Market is open for morning (9:30 AM ET) and midday (12:00 PM ET) sessions.
// Close (3:50 PM ET) is after regular hours — no new orders.
const isMarketOpen = orchInput.session_type === 'morning' || orchInput.session_type === 'midday';

// ── DERIVE ORCHESTRATOR SESSION TYPE FOR STORAGE ─────────────────────────────
// session_id carries '_watchdog' suffix for watchdog-triggered runs.
// Use 'watchdog_flip' label in orchestrator_sessions table so they're
// distinguishable from same-slot scheduled runs when loading context.
const rawSessionId       = (orchInput.portfolio_state.session_id || '');
const orchestratorSessionType = rawSessionId.endsWith('_watchdog')
  ? 'watchdog_flip'
  : (orchInput.session_type || 'unknown');

// ── OUTPUT ────────────────────────────────────────────────────────────────────
return [{
  json: {
    // Core orchestrator decisions
    is_market_open:            isMarketOpen,
    portfolio_actions:         enrichedActions,
    portfolio_review:          parsed.portfolio_review         || [],
    watchlist:                 parsed.watchlist                 || [],
    rejected_candidates:       parsed.rejected_candidates      || [],
    risk_summary:              parsed.risk_summary             || null,
    cash_deployment_rationale: parsed.cash_deployment_rationale || '',
    orchestrator_summary:      parsed.orchestrator_summary      || '',

    // Derived
    closing_positions:  closedPositions,
    opening_positions:  openingActions,
    post_mortem_payloads: postMortemPayloads,
    open_positions:     state.positions || [],  // Alpaca positions list (used by 09 for long/short split)

    // For Neon snapshot
    session_id:              orchInput.portfolio_state.session_id,
    session_type:            orchInput.session_type,
    orchestrator_session_type: orchestratorSessionType,
    account:      orchInput.portfolio_state.account,
    spyCurrent:       orchInput.portfolio_state.spyCurrent,
    spyCumulativePct: orchInput.portfolio_state.spyCumulativePct,
    prevSpyPrice:     orchInput.portfolio_state.prevSpyPrice,

    // Raw for debugging
    raw_orchestrator_response: (rawText || '').substring(0, 5000),
    usage_tokens: rawResponse.usage ? rawResponse.usage.total_tokens : null,
  }
}];

// Node: Process Post-Trade
// Position: After Merge (trade execution branches reconverge)
// Builds the portfolio snapshot payload for Neon and collects
// post-mortem webhook payloads for SELL/COVER actions.
// Output: 1 item with all data needed for the two final Neon writes.

const orch     = $("Parse Orchestrator Output").first().json;
const account  = orch.account || {};

// Compute long/short breakdown from executed positions
// At this point the trades have fired — we'd need to re-fetch the portfolio.
// For now, use the orchestrator's account snapshot (close enough for this session).
const longValue  = Math.abs(parseFloat(account.long_market_value  || 0));
const shortValue = Math.abs(parseFloat(account.short_market_value || 0));
// account.unrealized_pl is passed from Alpaca via 02_compute_derived_metrics (total unrealized P&L across all positions)
const unrealPnl  = parseFloat(account.unrealized_pl || 0);

// Build positions JSON for snapshot (current state before trades fully settle)
const positionsJson = (orch.portfolio_review || []).map(p => ({
  ticker:          p.ticker,
  action:          p.current_action,
  thesis_intact:   p.thesis_intact,
  earnings_risk:   p.earnings_risk,
  stop_proximity:  p.stop_proximity,
}));

// Separate longs and shorts using actual Alpaca position qty (qty < 0 = short)
const shortTickers = new Set(
  (orch.open_positions || []).filter(p => parseFloat(p.qty) < 0).map(p => p.symbol)
);
const longReviews  = positionsJson.filter(p => !shortTickers.has(p.ticker));
const shortReviews = positionsJson.filter(p =>  shortTickers.has(p.ticker));

// Escape single quotes for SQL string interpolation ('' is PostgreSQL's escape for ')
const sqlEsc = s => (s || '').replace(/'/g, "''");

// Snapshot row for Neon
const snapshotPayload = {
  session:             orch.session_id,
  portfolio_value_usd: parseFloat(account.portfolio_value),
  cash_usd:            parseFloat(account.cash),
  long_value_usd:      longValue,
  short_value_usd:     shortValue,
  unrealized_pnl_usd:  unrealPnl,
  spy_price:           orch.spyCurrent || null,
  spy_return_pct:      (orch.spyCurrent && orch.prevSpyPrice && orch.prevSpyPrice > 0)
    ? parseFloat(((orch.spyCurrent - orch.prevSpyPrice) / orch.prevSpyPrice * 100).toFixed(4))
    : null,
  spy_cumulative_pct:  orch.spyCumulativePct || 0,
  orchestrator_summary: sqlEsc(orch.orchestrator_summary),
  positions_json:      sqlEsc(JSON.stringify(longReviews)),
  short_positions_json: sqlEsc(JSON.stringify(shortReviews)),
  raw_json:            sqlEsc(JSON.stringify({
    portfolio_actions:         orch.portfolio_actions,
    cash_deployment_rationale: orch.cash_deployment_rationale,
  })),
};

// New watchlist items (replace entire watchlist each session)
const newWatchlist = (orch.watchlist || []).map(w => ({
  ticker:    w.ticker,
  niche:     w.niche,
  direction: w.direction,
  reason:    w.reason || '',
}));

// Post-mortem payloads (one per SELL/COVER)
// These are sent as webhook calls to the post-mortem workflow.
const postMortemPayloads = (orch.post_mortem_payloads || []).map(pm => ({
  ...pm,
  orchestrator_summary: orch.orchestrator_summary,
}));

return [{
  json: {
    snapshot:              snapshotPayload,
    watchlist:             newWatchlist,
    post_mortem_payloads:  postMortemPayloads,
    has_post_mortems:      postMortemPayloads.length > 0,
    session_id:            orch.session_id,
  }
}];

const input = $("Process Post-Trade").first().json;
const wl = input.watchlist || [];
const esc = s => (s||'').replace(/'/g,"''");
let sql = "DELETE FROM stocks.watchlist;";
if (wl.length > 0) {
  const vals = wl.map(w=>`('${esc(w.ticker)}','${esc(w.niche)}','${esc(w.direction)}','${esc(w.reason||'').substring(0,500)}')`).join(',');
  sql += ` INSERT INTO stocks.watchlist (ticker,niche,direction,reason) VALUES ${vals};`;
}
return [{json:{watchlist_sql:sql}}];

const input = $("Process Post-Trade").first().json;
const payloads = input.post_mortem_payloads || [];
if (payloads.length === 0) return [];
return payloads.map(p => ({json: p}));

// Node: Prepare Trade Actions
// Position: After IF "Is Market Open?" (TRUE branch)
// Input: orchestrator output (1 item)
// Output: N items — one per portfolio_action that should execute
// Each item is passed through the HTTP Request node that submits the Alpaca order.

const orch = $input.first().json;

if (!orch.is_market_open) {
  // Safety check — should not reach here given the IF node, but guard anyway
  return [];
}

const actions = orch.portfolio_actions || [];

if (actions.length === 0) {
  return [];
}

// For SELL/COVER: find the GTC trailing stop order to cancel before closing.
// Cancelling the stop first unlocks shares so DELETE /v2/positions works.
const openOrders = $("Compute Derived Metrics").first().json.openOrders || [];

// ── HARD LIMIT ENFORCEMENT ────────────────────────────────────────────────────
// These limits are enforced in code regardless of what the orchestrator outputs.
// SELL/COVER always pass through — they reduce exposure, never add it.

const MAX_POSITIONS  = 12;
const MAX_SHORT_USD  = 12000;
// Per sector: max 2 longs (1st free; 2nd requires TREND + ≤$5k) + 1 short

// Build current state from open positions (pre-trade snapshot)
const currentPositions = $("Compute Derived Metrics").first().json.positions || [];
const openTickers = new Set(currentPositions.map(p => p.symbol));
let openCount    = currentPositions.length;
let shortExposure = currentPositions
  .filter(p => parseFloat(p.qty) < 0)
  .reduce((sum, p) => sum + Math.abs(parseFloat(p.market_value)), 0);

// Count current longs and shorts per niche
const nicheCount = {};
for (const p of currentPositions) {
  const niche = $("Compute Derived Metrics").first().json.priceMap
    ? null  // niche not in positions directly; use action.niche from orchestrator
    : null;
  // We'll track niche counts from the positions via symbol→niche mapping below
}

// Build niche→{long,short} count from current positions using orchestrator's niche field
// We use the portfolio_review entries which list ticker+niche context, or fall back to
// matching tickers against the orchestrator's portfolio_actions context.
// Simplest reliable approach: parse niche from the open positions using the TICKER_NICHE
// constant embedded here (mirrors lib/constants.ts).
const TICKER_NICHE = {
  CRWD:'cybersecurity',PANW:'cybersecurity',ZS:'cybersecurity',OKTA:'cybersecurity',
  FTNT:'cybersecurity',S:'cybersecurity',CYBR:'cybersecurity',TMUS:'cybersecurity',
  QLYS:'cybersecurity',TENB:'cybersecurity',
  LMT:'defense',RTX:'defense',NOC:'defense',GD:'defense',HII:'defense',
  LHX:'defense',KTOS:'defense',RCAT:'defense',PLTR:'defense',AXON:'defense',
  CCJ:'nuclear_uranium',UEC:'nuclear_uranium',NXE:'nuclear_uranium',DNN:'nuclear_uranium',
  SMR:'nuclear_uranium',OKLO:'nuclear_uranium',CEG:'nuclear_uranium',VST:'nuclear_uranium',
  ETR:'nuclear_uranium',NEE:'nuclear_uranium',
  FCX:'copper_minerals',SCCO:'copper_minerals',TECK:'copper_minerals',HBM:'copper_minerals',
  VALE:'copper_minerals',MP:'copper_minerals',LTHM:'copper_minerals',ALB:'copper_minerals',
  SQM:'copper_minerals',LAC:'copper_minerals',
  ARM:'semiconductors',AMAT:'semiconductors',LRCX:'semiconductors',KLAC:'semiconductors',
  ON:'semiconductors',TER:'semiconductors',NXPI:'semiconductors',MCHP:'semiconductors',
  MPWR:'semiconductors',SNPS:'semiconductors',
  ORCL:'enterprise_saas',NOW:'enterprise_saas',CRM:'enterprise_saas',DDOG:'enterprise_saas',
  SNOW:'enterprise_saas',ADBE:'enterprise_saas',NET:'enterprise_saas',TEAM:'enterprise_saas',
  WDAY:'enterprise_saas',MDB:'enterprise_saas',
  XOM:'oil_gas',CVX:'oil_gas',COP:'oil_gas',SLB:'oil_gas',HAL:'oil_gas',
  MPC:'oil_gas',PSX:'oil_gas',VLO:'oil_gas',OXY:'oil_gas',EOG:'oil_gas',
  EQIX:'data_centers',DLR:'data_centers',AMT:'data_centers',IREN:'data_centers',
  CORZ:'data_centers',VRT:'data_centers',SMCI:'data_centers',DELL:'data_centers',
  HPE:'data_centers',WDC:'data_centers',
};

const nicheExposure = {}; // niche → { long: count, short: count }
for (const p of currentPositions) {
  const niche = TICKER_NICHE[p.symbol];
  if (!niche) continue;
  if (!nicheExposure[niche]) nicheExposure[niche] = { long: 0, short: 0 };
  const side = parseFloat(p.qty) >= 0 ? 'long' : 'short';
  nicheExposure[niche][side]++;
}

// Cash guard + hard limits: filter each action
let remainingCash = parseFloat(orch.account?.cash || 0);
const filteredActions = actions.filter(action => {
  // SELL/COVER always pass — they reduce exposure
  if (action.action === 'SELL' || action.action === 'COVER') return true;

  const isBuy   = action.action === 'BUY';
  const isShort = action.action === 'SHORT';
  const niche   = action.niche;
  const side    = isBuy ? 'long' : 'short';
  const cost    = action.size_usd || 0;

  // 0. Already-open guard — block duplicate BUY/SHORT for a ticker already held
  if (openTickers.has(action.ticker)) {
    console.log(`[LIMIT] Skipping ${action.action} ${action.ticker}: position already open`);
    return false;
  }

  // 1. Max positions cap
  if (openCount >= MAX_POSITIONS) {
    console.log(`[LIMIT] Skipping ${action.action} ${action.ticker}: max ${MAX_POSITIONS} positions reached (${openCount} open)`);
    return false;
  }

  // 2. Per-sector limits: max 2 longs (with conditions) + 1 short
  const nicheCounts = nicheExposure[niche] || { long: 0, short: 0 };

  if (side === 'short') {
    if (nicheCounts.short >= 1) {
      console.log(`[LIMIT] Skipping SHORT ${action.ticker}: ${niche} already has 1 short (max 1 per sector)`);
      return false;
    }
  } else {
    // Long side
    if (nicheCounts.long >= 2) {
      console.log(`[LIMIT] Skipping BUY ${action.ticker}: ${niche} already has 2 longs (max 2 per sector)`);
      return false;
    }
    if (nicheCounts.long === 1) {
      // Second long — requires TREND pattern and $5k sizing
      const pattern = (action.signal_history_pattern || '').toUpperCase();
      if (pattern !== 'TREND') {
        console.log(`[LIMIT] Skipping second BUY ${action.ticker}: ${niche} already has 1 long — second long requires TREND pattern (got ${pattern || 'none'})`);
        return false;
      }
      if ((action.size_usd || 0) > 5000) {
        console.log(`[LIMIT] Skipping second BUY ${action.ticker}: second long in ${niche} must be sized at $5,000 or less (got $${action.size_usd})`);
        return false;
      }
    }
  }

  // 3. Max short exposure cap
  if (isShort && (shortExposure + cost) > MAX_SHORT_USD) {
    console.log(`[LIMIT] Skipping SHORT ${action.ticker}: would push short exposure to $${(shortExposure + cost).toFixed(0)} (max $${MAX_SHORT_USD})`);
    return false;
  }

  // 4. Cash guard
  if (cost > remainingCash) {
    console.log(`[LIMIT] Skipping ${action.action} ${action.ticker}: insufficient cash ($${remainingCash.toFixed(0)} < $${cost})`);
    return false;
  }

  // Action passes — update running counters
  remainingCash -= cost;
  openCount++;
  if (!nicheExposure[niche]) nicheExposure[niche] = { long: 0, short: 0 };
  nicheExposure[niche][side]++;
  if (isShort) shortExposure += cost;

  return true;
});

// Output one item per action. Each item carries everything the Alpaca HTTP Request needs.
return filteredActions.map(action => {
  // Look up the stop order ID for SELL/COVER so Cancel Stop Before Close can cancel it
  let stop_order_id = null;
  if (action.action === 'SELL' || action.action === 'COVER') {
    const stopOrder = openOrders.find(o =>
      o.symbol === action.ticker &&
      o.type === 'trailing_stop' &&
      ['new', 'accepted', 'pending_new'].includes(o.status)
    );
    stop_order_id = stopOrder?.id || null;
  }

  return {
    json: {
      // Trade identity
      action:          action.action,    // BUY | SELL | SHORT | COVER
      ticker:          action.ticker,
      niche:           action.niche,
      session_id:      orch.session_id,

      // Alpaca order payloads (pre-built in node 07)
      order_payload:       action.order_payload,
      trail_stop_payload:  action.trail_stop_payload,
      needs_trailing_stop: action.needs_trailing_stop,

      // For SELL/COVER: stop order to cancel before closing position
      stop_order_id,

      // For post-trade logging
      size_usd:             action.size_usd,
      shares:               action.shares,
      estimated_price:      action.estimated_price,
      conviction:           action.conviction,
      effective_confidence: action.effective_confidence,
      stop_pct_used:        action.stop_pct_used,
      thesis:               action.thesis,
      exit_reason:          action.exit_reason || null,
      signal_history_pattern: action.signal_history_pattern,
      size_adjustments_applied: action.size_adjustments_applied || [],
      feedback_note:        action.feedback_note || null,
    }
  };
});

// Merge bars from all 9 niche fetches into one response
const allBars = {};
const sourceNodes = [
  'Fetch Bars Cybersecurity', 'Fetch Bars Defense', 'Fetch Bars Nuclear',
  'Fetch Bars Copper', 'Fetch Bars AI Semis', 'Fetch Bars Cloud',
  'Fetch Bars Oil Gas', 'Fetch Bars Data Centers', 'Fetch Bars SPY',
];
for (const nodeName of sourceNodes) {
  try {
    const resp = $(nodeName).first().json;
    if (resp && resp.bars) Object.assign(allBars, resp.bars);
  } catch (_) {}
}
return [{ json: { bars: allBars } }];

// Node: Build [Niche] Message  (8 instances — one per specialist branch)
// Position: After Merge [Niche] RSS  →  Specialist [Niche] LLM
// Input: $input.all() = merged RSS items from 2 feeds for this niche
// Output: 1 item — { niche, session_id, system_prompt, user_prompt }
//
// Each instance has these 3 constants set to the specific niche:
//   const NICHE         = 'cybersecurity';
//   const NICHE_DISPLAY = 'Cybersecurity';
//   const TICKERS       = ['CRWD','PANW',...];
//
// Everything else is identical across all 8 nodes.

const NICHE         = 'cybersecurity';          // SET PER INSTANCE
const NICHE_DISPLAY = 'Cybersecurity';      // SET PER INSTANCE
const TICKERS       = ["CRWD","PANW","ZS","OKTA","FTNT","S","CYBR","TMUS","QLYS","TENB"];         // SET PER INSTANCE

const ctx = $("Compute Derived Metrics").first().json;

function formatStockData(tickers, priceMap, fundamentalsMap, earningsRows, etfData) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  return tickers.map(ticker => {
    const p    = priceMap[ticker]        || {};
    const f    = fundamentalsMap[ticker] || {};
    const earn = earningsRows.find(e => e.ticker === ticker);
    let earningsTag = 'NONE';
    if (earn && earn.earnings_date) {
      const days = Math.round((new Date(earn.earnings_date) - today) / 86400000);
      if      (days >= 0 && days <= 3) earningsTag = `HIGH (${days}d — ${earn.earnings_date})`;
      else if (days >= 4 && days <= 7) earningsTag = `MEDIUM (${days}d — ${earn.earnings_date})`;
    }
    const pctFrom52H = p.week_52_high ? ((p.current - p.week_52_high) / p.week_52_high * 100).toFixed(1) : 'N/A';
    const pctFrom52L = p.week_52_low  ? ((p.current - p.week_52_low)  / p.week_52_low  * 100).toFixed(1) : 'N/A';
    const totalAnalysts = (f.analyst_buy||0) + (f.analyst_hold||0) + (f.analyst_sell||0);
    const buyPct = totalAnalysts > 0 ? Math.round((f.analyst_buy||0) / totalAnalysts * 100) : null;
    const analystStr = totalAnalysts > 0
      ? `${f.analyst_buy||0}B / ${f.analyst_hold||0}H / ${f.analyst_sell||0}S (${buyPct}% buy)`
      : 'N/A';
    let ptStr = 'N/A';
    if (f.price_target_avg && p.current) {
      const upside = ((f.price_target_avg - p.current) / p.current * 100);
      const upsideStr = upside >= 0 ? `+${upside.toFixed(1)}% upside` : `${upside.toFixed(1)}% — above PT`;
      let spreadStr = '';
      if (f.price_target_high && f.price_target_low && f.price_target_avg > 0) {
        const spread = (f.price_target_high - f.price_target_low) / f.price_target_avg * 100;
        const spreadLabel = spread > 40 ? ' — wide' : spread > 20 ? ' — moderate' : '';
        spreadStr = ` | Spread: $${f.price_target_low}–$${f.price_target_high} (${spread.toFixed(0)}%${spreadLabel})`;
      }
      ptStr = `$${f.price_target_avg} (${upsideStr})${spreadStr}`;
    }
    const revGrowth   = f.revenue_growth_yoy != null ? (f.revenue_growth_yoy * 100).toFixed(1) + '%' : 'N/A';
    const grossMargin = f.gross_margin       != null ? (f.gross_margin       * 100).toFixed(1) + '%' : 'N/A';
    const netMargin   = f.net_margin         != null ? (f.net_margin         * 100).toFixed(1) + '%' : 'N/A';
    let rsStr = 'N/A';
    if (etfData && p.chg_1d_pct != null && etfData.chg_1d_pct != null) {
      const s = v => (v >= 0 ? `+${v.toFixed(1)}` : v.toFixed(1));
      rsStr = `1D: ${s(p.chg_1d_pct - etfData.chg_1d_pct)}% | 5D: ${s(p.chg_5d_pct - etfData.chg_5d_pct)}% | 30D: ${s(p.chg_30d_pct - etfData.chg_30d_pct)}%`;
    }
    const fv = v => v >= 1e6 ? (v / 1e6).toFixed(1) + 'M' : v >= 1e3 ? Math.round(v / 1e3) + 'K' : (v || 0).toString();
    const volStr = p.adv_ratio != null
      ? `${fv(p.vol_today)} (ADV20: ${fv(p.adv_20)}) | Ratio: ${p.adv_ratio}x`
      : 'N/A';
    return [
      `${ticker}:`,
      `  Price: $${p.current||'N/A'} | 1D: ${p.chg_1d_pct||0}% | 5D: ${p.chg_5d_pct||0}% | 30D: ${p.chg_30d_pct||0}%`,
      `  vs ETF: ${rsStr}`,
      `  Volume: ${volStr}`,
      `  52W Range: $${p.week_52_low||'N/A'} – $${p.week_52_high||'N/A'} (${pctFrom52H}% from high / +${pctFrom52L}% from low)`,
      `  P/E: ${f.pe_ratio||'N/A'} | P/S: ${f.ps_ratio||'N/A'} | P/B: ${f.pb_ratio||'N/A'}`,
      `  Rev Growth YoY: ${revGrowth} | Gross Margin: ${grossMargin} | Net Margin: ${netMargin}`,
      `  Beta: ${f.beta||'N/A'} | Consensus: ${analystStr} | PT: ${ptStr}`,
      `  Earnings Risk: ${earningsTag}`,
    ].join('\n');
  }).join('\n\n');
}

function formatNews(allItems) {
  if (!allItems || allItems.length === 0) return 'No recent news retrieved.';
  return allItems.slice(0, 10).map((item, i) => {
    const a = item.json;
    const date = (a.isoDate || a.pubDate || '').substring(0, 10);
    return `[${i+1}] ${a.title||''}${date ? ` (${date})` : ''}\n${(a.contentSnippet||a.content||'').substring(0, 400)}`;
  }).join('\n\n');
}

function formatAccuracyHistory(niche, specialistEffectiveConf) {
  const acc          = specialistEffectiveConf[niche];
  const totalSignals = acc ? (acc.total_signals || 0) : 0;

  if (totalSignals === 0) {
    return 'COLD-START: No signal history on record yet. Report your honest confidence based purely on your sector analysis — fundamentals, technicals, and news. The system applies automatic calibration to your output. Do not anchor your confidence to any fixed value; report what the data actually supports.';
  }
  if (totalSignals < 5) {
    return `COLD-START (${totalSignals}/10 sessions recorded): Limited history for calibration. Report your honest confidence based on your analysis. The system scales your output automatically using your accumulating track record. Focus on accurate analysis, not on hitting any particular number.`;
  }
  if (totalSignals < 10) {
    return `WARMING UP (${totalSignals}/10 sessions recorded): Calibration is building. Report your honest confidence — the system applies your track record as a scaling factor. Full calibration unlocks at 10 sessions. Continue prioritising accuracy over confidence level.`;
  }

  const calLabel = acc.scaling_factor < 0.85
    ? 'YOU ARE OVERCONFIDENT — discount your stated confidence'
