    : acc.scaling_factor > 1.15 ? 'You have been underconfident — you may state slightly higher confidence'
    : 'Well-calibrated';
  return [
    `30-Day Performance: ${(acc.hit_rate * 100).toFixed(1)}% directional accuracy across ${acc.total_signals} signals`,
